CREATE TABLE game_price (id BIGINT NOT NULL AUTO_INCREMENT,edition_id BIGINT NOT NULL,region_code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount_minor BIGINT NOT NULL,active_from DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),active_until DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),open_price TINYINT GENERATED ALWAYS AS(IF(active_until IS NULL,1,NULL)) STORED,PRIMARY KEY(id),CONSTRAINT uk_game_price_active_key UNIQUE(edition_id,region_code,currency,active_from),CONSTRAINT uk_game_price_one_active UNIQUE(edition_id,region_code,currency,open_price),KEY idx_game_price_lookup(edition_id,region_code,currency,active_from DESC),CONSTRAINT ck_game_price_region CHECK(REGEXP_LIKE(region_code,'^[A-Z0-9-]{2,16}$','c')),CONSTRAINT ck_game_price_currency CHECK(REGEXP_LIKE(currency,'^[A-Z]{3}$','c')),CONSTRAINT ck_game_price_amount CHECK(amount_minor>=0),CONSTRAINT ck_game_price_window CHECK(active_until IS NULL OR active_until>active_from),CONSTRAINT fk_game_price_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
